def find_path(graph, start, goal):
    # Initialize stack for DFS
    stack = [(start, [start])]

    while stack:
        (current, path) = stack.pop()
        for next in set(graph[current] - set(path)):
            if next == goal:
                yield path + [next]
            else:
                stack.append((next, path + [next]))

