    visited = set()

    while stack:
        (vertex, path) = stack.pop()
        if vertex not in visited:
            visited.add(vertex)
            for next_vertex in graph[vertex]:
                if next_vertex == goal:
                    return path + [goal]
                else:
                    stack.append((next_vertex, path + [next_vertex]))
