def find_path(graph, start, goal):
    visited = set()  # To keep track of visited nodes to avoid cycles
    path_stack = []  # Stack for depth-first search
    path_stack.append([start])  # Start with the start node on the path

    while path_stack:
        path = path_stack.pop()
        node = path[-1]

        if node not in visited:
            visited.add(node)
            if node == goal:
                return path  # Found a path from start to goal
            else:
                for neighbour in graph.get(node, []):
                    new_path = list(path)
                    new_path.append(neighbour)
                    path_stack.append(new_path)

    return None  # Goal is unreachable
